"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Progress Circle: generated by UIX from the design system. Same variants and sizes as the Figma component.

const progressCircleVariants = cva(
  "skin-quiet relative inline-flex shrink-0 items-center justify-center text-fg-primary",
  {
    variants: {
      size: {
        sm: "size-10 text-label-small",
        md: "size-16 text-label-medium",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

export interface ProgressCircleProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof progressCircleVariants> {
  /** 0 to 100. */
  value?: number;
}

const ProgressCircle = React.forwardRef<HTMLDivElement, ProgressCircleProps>(
  ({ className, size, value = 0, children, ...props }, ref) => {
    const percent = Math.min(100, Math.max(0, value));
    return (
      <div data-slot="progress-circle" data-kind="track" ref={ref} role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={percent} className={cn(progressCircleVariants({ size }), className)} {...props}>
        <svg viewBox="0 0 36 36" aria-hidden className="size-full -rotate-90">
          <circle cx="18" cy="18" r="15.9155" fill="none" strokeWidth="3" className="stroke-muted" />
          {percent > 0 ? <circle cx="18" cy="18" r="15.9155" fill="none" strokeWidth="3" strokeLinecap="round" strokeDasharray={percent + " 100"} className="stroke-brand" /> : null}
        </svg>
        <span className="absolute">{children ?? percent + "%"}</span>
      </div>
    );
  },
);
ProgressCircle.displayName = "ProgressCircle";

export { ProgressCircle, progressCircleVariants };
